INSERT INTO `citizen_profiles` (`user_id`,`dob`,`gender`,`state`,`district`,`category`,`occupation`,`annual_income`,`education`) VALUES
(2,'2000-05-15','Male','Gujarat','Surat','General','Private Employee',300000.00,'Graduate');
INSERT INTO `schemes` (`scheme_name`,`category`,`state`,`keywords`,`short_description`,`description`,`who_can_apply`,`eligibility`,`benefits`,`documents_required`,`how_to_apply`,`official_application_link`,`image`,`status`) VALUES
('Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)','Agriculture','All India','pm-kisan, farmer, income support, agriculture','Income support scheme for eligible landholding farmer families.','PM-KISAN is a Central Sector Scheme that provides income support to eligible landholding farmer families, subject to the scheme''s exclusion criteria. Benefits are transferred directly to eligible beneficiaries through DBT.','Eligible landholding farmer families, subject to the exclusions and verification requirements under PM-KISAN.','Farmer family should have eligible cultivable landholding recorded in the relevant land records; institutional landholders and specified higher-income/professional categories are excluded.','Income support of ₹6,000 per year, released in three instalments of ₹2,000 each to eligible beneficiaries.','Aadhaar; landholding/land record details; bank account details; other state-specific verification documents if required.','Visit the PM-KISAN portal or approach the designated registration facility/CSC. Complete farmer registration and submit the required land and bank details.','https://pmkisan.gov.in/','assets/images/schemes/pm-kisan.jpg','active'),
('Pradhan Mantri Fasal Bima Yojana (PMFBY)','Agriculture','All India','crop insurance, farmer, crop loss, insurance','Crop insurance support against notified crop risks and losses.','PMFBY is the Government of India''s crop insurance scheme for notified crops and areas. It provides insurance protection against specified crop losses and offers online tools for enrolment, premium calculation and claim/status tracking.','Farmers growing notified crops in notified areas during the applicable season, subject to scheme and state notification conditions.','Eligibility depends on the notified crop, area, season and applicable state/UT implementation rules. Farmers should check the current season notification before applying.','Crop insurance protection for notified risks; premium and claim rules depend on crop, season and government notification.','Aadhaar/identity proof; bank account details; land/cultivation records; sowing/crop details; other documents required by the notified process.','Use the official PMFBY Farmer Corner to check the current season, calculate premium and enrol online where enabled, or apply through the designated bank/insurance channel.','https://pmfby.gov.in/','assets/images/schemes/pmfby.jpg','active'),
('Kisan Credit Card (KCC)','Agriculture','All India','kcc, farmer credit, crop loan, agriculture loan','Flexible agricultural credit support for cultivation and allied activities.','The Kisan Credit Card scheme provides timely credit support to farmers for crop cultivation, post-harvest expenses, marketing, household consumption needs related to farming, maintenance of farm assets and certain agricultural investment activities.','Owner cultivators, tenant farmers, oral lessees, sharecroppers and eligible farmer groups such as SHGs/JLGs, subject to bank norms.','The applicant must be an eligible farmer and satisfy the lending bank''s documentation, credit and security requirements.','Access to a simplified agricultural credit facility; eligible crop-loan components may receive government interest subvention and prompt repayment incentive benefits as per current rules.','Application form; identity/address proof; landholding/cultivation proof; cropping pattern; photographs; bank-required security documents where applicable.','Apply through the bank where you maintain an account or another participating bank. Select the Kisan Credit Card facility, submit the application and required documents, and complete bank verification.','https://www.myscheme.gov.in/schemes/kcc','assets/images/schemes/kcc.jpg','active'),
('Pradhan Mantri Kisan Urja Suraksha evam Utthaan Mahabhiyan (PM-KUSUM)','Agriculture','All India','solar pump, farmer, solar energy, irrigation','Supports solar energy solutions for agriculture and solarisation of farm power systems.','PM-KUSUM aims to reduce dependence on diesel in agriculture, promote renewable energy and improve farmer income through solar power plants and solarisation of agricultural pumps under its notified components.','Eligible farmers and other implementing beneficiaries covered by the relevant PM-KUSUM component and state implementation guidelines.','Eligibility and subsidy structure vary by component and state. Applications are handled by designated state implementing agencies/discoms.','Capital support/subsidy for eligible solarisation components, including support for standalone solar pumps and grid-connected agricultural pump solarisation under applicable guidelines.','Aadhaar/identity proof; land documents; electricity/pump details; bank account; photographs; state-agency documents as required.','Visit the National PM-KUSUM Portal and follow the application route provided for your state/component. Apply through the designated state agency/discom.','https://pmkusum.mnre.gov.in/','assets/images/schemes/pm-kusum.jpg','active'),
('Pradhan Mantri Krishi Sinchayee Yojana - Per Drop More Crop','Agriculture','All India','micro irrigation, drip, sprinkler, water efficiency','Promotes efficient farm water use through micro-irrigation technologies.','The Per Drop More Crop component of PMKSY focuses on improving water-use efficiency at farm level through micro-irrigation systems such as drip and sprinkler irrigation.','Farmers eligible under the current state implementation of the micro-irrigation component.','Eligibility, subsidy rates, crop coverage and application windows are governed by the implementing state and current guidelines.','Financial assistance/subsidy for eligible micro-irrigation systems that improve water-use efficiency.','Aadhaar/identity proof; land/cultivation documents; bank details; quotation/system details; other state-required documents.','Apply through the state agriculture/horticulture department or the designated online portal as notified for your state.','https://pmksy.gov.in/','assets/images/schemes/pmksy.jpg','active'),
('Soil Health Card Scheme','Agriculture','All India','soil health, soil testing, farmer, fertilizer','Provides soil nutrient information to help farmers use fertilizers appropriately.','The Soil Health Card system provides farmers with information on soil nutrient status and recommendations for balanced fertilizer use based on soil testing.','Farmers and land cultivators whose fields are covered by the soil testing and Soil Health Card programme.','Field sampling and eligibility are handled through the implementing state agriculture and soil-testing system.','Soil test results and fertilizer recommendations for the sampled farm plot.','Land/farm details; farmer identity/contact information; sample-related information as required by the local soil-testing process.','Use the official Soil Health Card system or contact the local agriculture/soil-testing authority to get soil samples tested and obtain the card/report.','https://soilhealth.dac.gov.in/','assets/images/schemes/soil-health-card.jpg','active'),
('e-NAM (National Agriculture Market)','Agriculture','All India','e-nam, mandi, agricultural market, farmer, trading','Online agricultural market platform intended to improve transparent price discovery and market access.','e-NAM integrates agricultural markets and provides an electronic trading platform intended to improve price discovery, transparency and market access for farmers, traders and other market participants.','Farmers and eligible market participants registered with participating agricultural markets/APMCs.','Registration and trading access depend on the participating mandi/APMC and applicable state rules.','Online access to market information, bidding/trading facilities where enabled, and better price discovery.','Identity/contact details; bank/payment details; market/APMC registration details and other documents as required.','Visit the e-NAM portal, register using the available participant route, and complete the onboarding required by the participating mandi/APMC.','https://www.enam.gov.in/','assets/images/schemes/e-nam.jpg','active'),
('Pradhan Mantri Matsya Sampada Yojana (PMMSY)','Fisheries','All India','fisheries, fish farming, aquaculture, pmmsy','Supports fisheries development, infrastructure, aquaculture and livelihoods.','PMMSY is a fisheries-sector scheme supporting sustainable fisheries development, productivity, infrastructure, value chains and livelihoods through eligible components implemented by central and state agencies.','Eligible individuals, fishers, fish farmers, entrepreneurs, SHGs, cooperatives, organisations and other beneficiaries specified in the applicable component guidelines.','Eligibility, project cost, subsidy and implementation arrangements vary by component and state.','Financial assistance/subsidy and infrastructure or livelihood support according to the applicable PMMSY component.','Identity/address proof; bank account; land/lease proof where required; project proposal/DPR where applicable; caste certificate for reserved-category components where applicable.','Apply through the designated fisheries department/online state portal or other notified implementing agency for the relevant PMMSY component.','https://pmmsy.dof.gov.in/','assets/images/schemes/pmmsy.jpg','active'),
('Pradhan Mantri Kisan Maandhan Yojana (PM-KMY)','Social Welfare','All India','farmer pension, pm-kmy, old age pension, small marginal farmer','Voluntary contributory pension scheme for eligible small and marginal farmers.','PM-KMY provides old-age social security to eligible small and marginal farmers through a voluntary contributory pension arrangement with government matching contribution under scheme rules.','Small and marginal farmers with eligible landholding, generally aged 18 to 40 years, meeting the scheme''s inclusion and exclusion rules.','Cultivable landholding is generally limited to 2 hectares; age at entry is 18-40 years; specified institutional, government-service, pension and income-tax/professional exclusions apply.','Minimum assured pension of ₹3,000 per month after attaining age 60, with additional family-pension provisions according to scheme rules.','Aadhaar; savings bank account/PM-KISAN account details; land record details; mobile/contact details.','Enrol through the nearest Common Service Centre (CSC) or the official Maandhan process. Complete Aadhaar and bank details and the contribution mandate.','https://www.myscheme.gov.in/schemes/pmkmdy','assets/images/schemes/pm-kisan-maandhan.jpg','active'),
('PM Vishwakarma','Skill Development','All India','artisan, craftsperson, pm vishwakarma, toolkit, credit','End-to-end support for artisans and craftspeople in traditional trades.','PM Vishwakarma supports artisans and craftspeople through recognition, skill training, toolkit support, collateral-free enterprise loans, digital transaction incentives and market linkage support.','Artisans and craftspeople working with hands/tools in one of the 18 notified traditional trades and meeting the scheme conditions.','Applicant must generally be at least 18, work in an eligible trade on self-employment basis, and satisfy restrictions on prior similar loans and government employment.','Recognition certificate/ID, skill training, ₹15,000 toolkit incentive, collateral-free enterprise loans in eligible tranches and support for digital transactions and market linkage.','Aadhaar; mobile number; bank details; ration card or family-related documents as specified; additional documents if required.','Register through the official PM Vishwakarma portal, commonly with assistance from the nearest CSC, and complete the verification process.','https://pmvishwakarma.gov.in/','assets/images/schemes/pm-vishwakarma.jpg','active'),
('Pradhan Mantri SVANidhi','Employment & Livelihood','All India','street vendor, svanidhi, micro credit, vendor','Working-capital credit support for eligible street vendors.','PM SVANidhi provides structured working-capital support to eligible street vendors and promotes digital transactions and responsible credit behaviour.','Eligible street vendors/hawkers identified or supported under the applicable urban local body and scheme rules.','Eligibility depends on street-vendor status, survey/certificate/letter of recommendation and the applicable scheme guidelines.','Collateral-free working-capital loan support with incentives for eligible digital transactions and timely repayment under current scheme rules.','Identity proof; street-vendor certificate/LoR where applicable; bank account details; mobile number and other ULB-required documents.','Apply through the PM SVANidhi portal, participating lending institution, or through the designated urban local body facilitation process.','https://pmsvanidhi.mohua.gov.in/','assets/images/schemes/pm-svanidhi.jpg','active'),
('Prime Minister''s Employment Generation Programme (PMEGP)','Employment & Entrepreneurship','All India','pmegp, entrepreneurship, business loan, subsidy, msme','Credit-linked support for setting up eligible micro-enterprises.','PMEGP is a credit-linked subsidy programme implemented through designated agencies to support new micro-enterprises and create self-employment opportunities.','Eligible individuals and other beneficiary categories permitted under PMEGP guidelines for new viable micro-enterprises.','Applicant and project must satisfy current PMEGP guidelines, including project type, age, contribution, location and prior-subsidy restrictions.','Margin-money subsidy linked to the eligible project cost, with the balance financed through the lending institution subject to scheme and bank norms.','Aadhaar; project report; identity/address proof; education/skill documents where applicable; category certificates where applicable; bank documents.','Apply online through the PMEGP e-portal, submit the project proposal and complete scrutiny, training and bank-loan formalities where applicable.','https://www.kviconline.gov.in/pmegpeportal/','assets/images/schemes/pmegp.jpg','active'),
('Pradhan Mantri MUDRA Yojana (PMMY)','Employment & Entrepreneurship','All India','mudra, small business, micro enterprise, loan','Business loans for eligible micro and small income-generating activities.','PMMY supports micro-enterprises with institutional credit through participating lenders under products such as Shishu, Kishore and Tarun, subject to current lending rules.','Micro and small entrepreneurs engaged in eligible non-farm income-generating activities and other activities covered by MUDRA guidelines.','The borrower must satisfy the participating lender''s credit, KYC and business requirements; loan category depends on the amount and stage of the business.','Collateral-free or appropriately secured credit support under eligible MUDRA products, subject to lender norms and current guidelines.','KYC/identity proof; address proof; bank statements; business/project documents; quotations or registrations where required by the lender.','Approach a participating bank, NBFC or MFI or use the official MUDRA information portal to understand the product and lender process.','https://www.mudra.org.in/','assets/images/schemes/mudra.jpg','active'),
('Stand-Up India Scheme','Employment & Entrepreneurship','All India','stand up india, women entrepreneur, sc/st entrepreneur, startup loan','Bank-loan support for greenfield enterprises promoted by women and SC/ST entrepreneurs.','Stand-Up India facilitates bank loans for setting up greenfield enterprises by eligible Scheduled Caste/Scheduled Tribe borrowers and women entrepreneurs, subject to scheme and lender norms.','Women entrepreneurs and SC/ST entrepreneurs meeting the current scheme conditions for a greenfield enterprise.','Applicant must meet age, ownership/control, enterprise, credit-history and other conditions of the scheme and lending institution.','Composite loans generally ranging from ₹10 lakh to ₹1 crore for eligible greenfield enterprises, subject to applicable guidelines and bank appraisal.','Identity/address proof; caste certificate where applicable; business/project report; financial and bank documents; promoter contribution details.','Use the Stand-Up India portal to explore the handholding and application route or approach a participating bank.','https://www.standupmitra.in/','assets/images/schemes/stand-up-india.jpg','active'),
('Pradhan Mantri Formalisation of Micro Food Processing Enterprises (PM-FME)','Food Processing & Entrepreneurship','All India','pmfme, food processing, micro enterprise, subsidy, odop','Supports formalisation and upgradation of micro food-processing enterprises.','PM-FME provides financial, technical and business support for setting up or upgrading eligible micro food-processing enterprises and promotes value addition, capacity building and One District One Product approaches.','Existing or eligible new micro food-processing enterprises, SHGs, FPOs, cooperatives and other eligible groups under applicable components.','Eligibility, project conditions, beneficiary type and support vary by component and current guidelines.','Credit-linked capital subsidy for eligible units, seed capital for eligible SHG members, common-infrastructure support, branding/marketing and capacity-building assistance under the programme.','Identity/address proof; business details; project report; bank documents; enterprise/FSSAI/Udyam-related documents where applicable.','Use the official PMFME portal and state/UT implementation route. Eligible applicants may receive handholding support from designated agencies/DRPs.','https://pmfme.mofpi.gov.in/','assets/images/schemes/pmfme.jpg','active'),
('Pradhan Mantri Jan-Dhan Yojana (PMJDY)','Financial Inclusion','All India','jan dhan, bank account, financial inclusion, dbt','Provides access to basic banking and financial services for unbanked persons.','PMJDY is the national financial-inclusion mission providing access to basic savings bank accounts and linking eligible customers with remittance, credit, insurance, pension and DBT services.','Persons who do not have another basic bank account and meet the account-opening requirements of participating banks/Business Correspondents.','Account opening is subject to KYC requirements and bank verification; product-linked benefits may have additional conditions.','Basic savings account with no minimum-balance requirement under the scheme, RuPay debit card and access to eligible overdraft/DBT/insurance/pension linkages subject to rules.','Aadhaar or other officially accepted KYC document; address/identity proof; photograph and mobile number as applicable.','Visit a participating bank branch or Business Correspondent (Bank Mitra) and request a PMJDY account.','https://pmjdy.gov.in/','assets/images/schemes/pmjdy.jpg','active'),
('Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)','Insurance & Social Security','All India','pmjjby, life insurance, bank account, insurance','Low-cost renewable life insurance cover for eligible bank/post-office account holders.','PMJJBY is a one-year renewable life insurance scheme offering death cover to eligible subscribers through participating banks/post offices, subject to scheme rules.','Individual bank or post-office account holders in the prescribed age band who consent to join and meet scheme conditions.','Entry and continuation are subject to the current age, account, consent, premium, auto-debit and other terms of the scheme.','Life cover of ₹2 lakh on death due to any cause, subject to the policy terms, with annual premium collected through auto-debit.','Bank/post-office account details; KYC; consent/auto-debit mandate and nominee details.','Enrol through a participating bank/post office or follow the Jan Suraksha process provided by the financial institution.','https://jansuraksha.gov.in/','assets/images/schemes/pmjjby.jpg','active'),
('Pradhan Mantri Suraksha Bima Yojana (PMSBY)','Insurance & Social Security','All India','pmsby, accident insurance, bank account, disability','Affordable accident insurance for eligible bank/post-office account holders.','PMSBY is an annual renewable personal accident insurance scheme that provides cover for accidental death and specified permanent disabilities, subject to current terms.','Individual bank/post-office account holders aged 18 to 70 years who consent to join and meet the scheme conditions.','Eligibility depends on age, account ownership, consent/auto-debit and the current scheme terms.','Accidental death or specified disability cover up to ₹2 lakh, with ₹1 lakh for specified partial disability, as per the scheme terms.','Bank/post-office account details; KYC; consent/auto-debit mandate and nominee details.','Enrol through the participating bank/post office or use the official Jan Suraksha forms/process.','https://jansuraksha.gov.in/','assets/images/schemes/pmsby.jpg','active'),
('Atal Pension Yojana (APY)','Pension & Social Security','All India','atal pension, apy, pension, unorganised workers','Voluntary pension scheme for eligible savings-account holders.','APY is a voluntary contributory pension scheme designed to provide old-age income security, particularly for workers in the unorganised sector.','Savings bank/post-office account holders aged 18 to 40 years who are eligible under the current APY rules.','Since 1 October 2022, a person who is or has been an income-tax payer is not eligible to join APY; other scheme conditions also apply.','Guaranteed minimum pension options of ₹1,000, ₹2,000, ₹3,000, ₹4,000 or ₹5,000 per month after age 60, subject to contribution and scheme rules.','Savings bank/post-office account; KYC details; nominee/spouse details; auto-debit consent.','Enrol through a participating bank/post office, internet banking facility where enabled, or the official APY route.','https://enps.nsdl.com/eNPS/NationalPensionSystem.html','assets/images/schemes/apy.jpg','active'),
('Sukanya Samriddhi Yojana (SSY)','Women & Child Welfare','All India','sukanya, girl child, savings, beti bachao, ss yojana','Small-savings account scheme designed for the future of a girl child.','Sukanya Samriddhi Yojana is a government small-savings scheme for a girl child, intended to encourage long-term savings for education and future needs.','Parents or legal guardians of an eligible girl child who meets the account-opening conditions.','The girl child must be an eligible resident Indian; the account is generally opened before she reaches age 10, with account limits and operating conditions prescribed by the scheme.','Government-notified interest on the account, tax benefits subject to applicable law and maturity/withdrawal rules under the scheme.','Girl child''s birth certificate; parent/guardian identity and address proof; photographs; other KYC documents required by the bank/post office.','Open the account through an authorised bank branch or post office and submit the account-opening form and KYC documents.','https://www.indiapost.gov.in/','assets/images/schemes/sukanya.jpg','active'),
('Pradhan Mantri Ujjwala Yojana (PMUY)','Energy & Household Welfare','All India','ujjwala, lpg, women, clean cooking, pmuy','Supports eligible women from poor households with LPG connections.','PMUY promotes clean cooking by supporting eligible households, with the connection issued in the name of an eligible adult woman subject to the current scheme criteria and LPG distributor process.','Eligible adult women from deprived/poor households meeting PMUY eligibility conditions and without an existing LPG connection in the household.','Eligibility and documentation depend on the prevailing PMUY criteria and household records; one LPG connection is permitted per eligible household as per rules.','Support towards a deposit-free LPG connection and applicable assistance/subsidy components under the current PMUY framework.','Aadhaar/identity proof; address proof; ration/family composition details; bank account details; KYC and other LPG distributor requirements.','Apply through the PMUY portal or an authorised LPG distributor. Select the appropriate LPG connection and submit KYC documents.','https://www.pmuy.gov.in/','assets/images/schemes/pmuy.jpg','active'),
('Pradhan Mantri Awas Yojana - Urban (PMAY-U) 2.0','Housing','All India','pmay urban, housing, ews, lig, mig, urban housing','Housing assistance framework for eligible urban households.','PMAY-U 2.0 supports eligible urban households through its notified verticals to provide pucca housing and improve housing access for economically weaker and other eligible groups in statutory towns and notified urban areas.','Eligible urban households falling within the notified EWS/LIG/MIG and other beneficiary categories under PMAY-U 2.0.','Eligibility includes income category, absence of an existing pucca house in the country and other mission conditions. Current city/ULB coverage and vertical-specific rules apply.','Central and state assistance/subsidy under the applicable PMAY-U 2.0 vertical, with the quantum determined by the state/UT and component.','Aadhaar; income proof/self-certificate; identity/residence proof; bank details; housing/property documents; category/minority documents if applicable.','Register through the official PMAY-U 2.0 portal and complete the eligibility check and beneficiary survey for the applicable vertical.','https://pmay-urban.gov.in/','assets/images/schemes/pmay-urban.jpg','active'),
('Pradhan Mantri Awaas Yojana - Gramin (PMAY-G)','Housing','All India','pmay gramin, rural housing, housing assistance, village','Rural housing assistance for eligible households without adequate housing.','PMAY-G aims to provide pucca houses with basic amenities to eligible rural households identified under the prescribed beneficiary-selection and verification process.','Eligible rural households included through the PMAY-G beneficiary-selection process and satisfying current programme conditions.','Eligibility is determined through the prescribed rural housing deprivation/priority data and verification by local authorities.','Financial assistance for construction of a pucca house along with convergence with basic-amenity programmes where applicable.','Aadhaar/identity proof; beneficiary and household details; bank/post-office account details; land/house-site documents where required.','Beneficiaries are generally identified through the programme''s prescribed process and may be assisted by the Gram Panchayat/block administration for verification and implementation.','https://pmayg.nic.in/','assets/images/schemes/pmay-gramin.jpg','active'),
('Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGA)','Employment & Livelihood','All India','mgnrega, rural employment, wage employment, job card','Provides a legal guarantee of rural wage employment for eligible households.','MGNREGA provides a legal guarantee of wage employment for rural households willing to do unskilled manual work, while creating durable community and rural assets through approved works.','Rural households whose adult members are willing to do unskilled manual work and who are eligible to be registered under the Act.','Registration is undertaken through the Gram Panchayat and job cards are issued to eligible rural households according to the Act and local verification.','Up to the statutory employment entitlement under the Act when demanded and subject to programme conditions, with wages paid according to notified state wage rates.','Household details; identity proof; photographs; address/residence information; other Gram Panchayat records as required.','Contact the Gram Panchayat, submit a household registration request and obtain a job card. Work can then be demanded through the local process.','https://nrega.nic.in/','assets/images/schemes/mgnrega.jpg','active'),
('Indira Gandhi National Old Age Pension Scheme (IGNOAPS)','Social Welfare','All India','old age pension, nsap, bpl, senior citizen','Social-security pension support for eligible older persons from poor households.','IGNOAPS is a component of the National Social Assistance Programme (NSAP) providing social-security pension support to eligible older persons from poor households, with state governments adding/implementing benefits as applicable.','Older persons from eligible poor/BPL households meeting the current NSAP and state conditions.','Age threshold, BPL/poverty criteria and state top-up/implementation rules must be checked for the applicant''s state.','Monthly social-security pension support; exact combined amount can vary by central and state contribution.','Age proof; Aadhaar/identity proof; BPL/poverty evidence where required; bank/post-office account; residence and other local documents.','Apply through the prescribed state/UT/local social-welfare or panchayat/municipal process for NSAP pensions.','https://nsap.nic.in/','assets/images/schemes/ignoaps.jpg','active'),
('Indira Gandhi National Widow Pension Scheme (IGNWPS)','Social Welfare','All India','widow pension, nsap, women welfare, pension','Social-security pension support for eligible widows from poor households.','IGNWPS is an NSAP component supporting eligible widows from poor households. States/UTs implement the pension and may provide additional benefits under their own rules.','Widows meeting the current central and state eligibility requirements, including the prescribed age and poverty/BPL conditions where applicable.','Age, BPL/poverty status and other conditions depend on the applicable central scheme and state implementation rules.','Monthly pension support, with the final benefit potentially including a state contribution/top-up.','Death certificate of spouse; age proof; identity/residence proof; BPL/poverty evidence where required; bank account details.','Apply through the state/UT social-welfare or local panchayat/municipal authority under the NSAP pension process.','https://nsap.nic.in/','assets/images/schemes/ignwps.jpg','active'),
('Indira Gandhi National Disability Pension Scheme (IGNDPS)','Disability & Social Welfare','All India','disability pension, nsap, divyangjan, pwd, pension','Pension support for eligible persons with severe disabilities from poor households.','IGNDPS is an NSAP component providing social-security pension support to eligible persons with severe disabilities who meet the prescribed central and state conditions.','Persons with prescribed disability levels from eligible poor/BPL households, subject to the current NSAP and state rules.','Age, disability percentage/type and poverty/BPL conditions are subject to current programme rules and state implementation.','Monthly pension support, with state governments potentially adding a top-up or additional assistance.','Disability certificate; age proof; Aadhaar/identity proof; BPL/poverty evidence where required; bank/post-office account.','Apply through the prescribed state/UT social-welfare, panchayat or municipal authority under NSAP.','https://nsap.nic.in/','assets/images/schemes/igndps.jpg','active'),
('National Family Benefit Scheme (NFBS)','Social Welfare','All India','family benefit, nsap, death of breadwinner, financial assistance','One-time family assistance for eligible households after the death of a primary breadwinner.','NFBS is an NSAP component that provides one-time financial assistance to eligible poor households following the death of the primary breadwinner, subject to scheme and state implementation rules.','Eligible poor/BPL households whose primary breadwinner dies and who satisfy the current age and dependency conditions.','The deceased breadwinner and household must meet the applicable scheme definitions and verification requirements.','One-time financial assistance to the eligible household; amount is governed by the current central/state rules.','Death certificate; identity and residence proof; BPL/poverty evidence where required; bank account and relationship/dependency documents.','Submit the prescribed application through the local panchayat/municipal or social-welfare authority under the NSAP process.','https://nsap.nic.in/','assets/images/schemes/nfbs.jpg','active'),
('Pradhan Mantri Shram Yogi Maandhan (PM-SYM)','Labour & Social Security','All India','pm-sym, unorganised workers, pension, labour','Voluntary contributory pension scheme for eligible unorganised workers.','PM-SYM is a contributory pension scheme intended to provide old-age security to eligible unorganised workers through worker contributions matched by the Government of India.','Unorganised workers generally aged 18 to 40 years with monthly income within the prescribed limit and meeting the scheme conditions.','Applicant must be an eligible unorganised worker and not be covered by excluded statutory social-security or pension schemes; current income and age rules apply.','Assured pension of ₹3,000 per month after attaining age 60, subject to continued contribution and scheme rules.','Aadhaar; bank account/savings account details; mobile number; occupation/income declaration as required.','Enrol through a Common Service Centre (CSC) or the official Maandhan process. Aadhaar and bank details are used for registration.','https://maandhan.in/','assets/images/schemes/pm-sym.jpg','active'),
('Pradhan Mantri Matru Vandana Yojana (PMMVY)','Women & Child Welfare','All India','pmmvy, maternity benefit, pregnant women, lactating mothers','Maternity benefit support for eligible pregnant women and lactating mothers.','PMMVY provides maternity benefit support to eligible women, with payments linked to prescribed conditions, registration and fulfilment of scheme milestones under the current guidelines.','Eligible pregnant women and lactating mothers covered by the scheme criteria, subject to exclusions and current guidelines.','Eligibility depends on the current PMMVY criteria, including pregnancy/childbirth status, beneficiary category and required registration/conditions.','Maternity benefit payments through DBT as per the current PMMVY benefit structure and conditions.','Aadhaar/identity proof; bank account; pregnancy/childbirth and health-related records; MCP/Anganwadi/health-facility documents as required.','Apply through the designated PMMVY/Anganwadi/health system or the current official portal used for PMMVY registration.','https://pmmvy.wcd.gov.in/','assets/images/schemes/pmmvy.jpg','active'),
('Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (AB-PMJAY)','Healthcare','All India','ayushman bharat, pm-jay, health insurance, hospitalisation','Cashless secondary and tertiary hospitalisation cover for eligible families.','AB-PMJAY is a Government of India health assurance scheme administered by the National Health Authority that provides cashless hospitalisation coverage to eligible poor and vulnerable families under the programme rules.','Eligible poor and vulnerable families identified/covered under the current PM-JAY beneficiary database and applicable expansion rules.','Eligibility depends on the official beneficiary database and current scheme rules; coverage and identity verification are performed through the PM-JAY system.','Health cover of up to ₹5 lakh per family per year for eligible secondary and tertiary care hospitalisation under the scheme.','Aadhaar/identity proof and beneficiary/family records; supporting documents may vary by verification route.','Check eligibility on the official PM-JAY portal or at an empanelled hospital/CSC, then complete beneficiary verification and obtain the Ayushman card where applicable.','https://pmjay.gov.in/','assets/images/schemes/ab-pmjay.jpg','active'),
('Prime Minister''s Internship Scheme (PMIS)','Skills & Employment','All India','pm internship, internship, youth, stipend, pminternship','12-month internship opportunities with participating companies for eligible youth.','The Prime Minister''s Internship Scheme provides structured 12-month internship opportunities in participating companies and combines workplace exposure with financial support and insurance coverage under the scheme framework.','Indian youth in the prescribed age and education bands who are not in full-time employment or full-time education and satisfy current PMIS conditions.','Current rules include an age band of 21-24 years on the last application date, no full-time employment/education and family income within the prescribed limit; other conditions apply.','Monthly assistance of ₹4,500 from Government of India and ₹500 from industry, plus a one-time ₹6,000 grant for incidentals; insurance is also provided under the scheme framework.','Aadhaar/identity proof; educational certificates; bank account; mobile number; income/family details and other portal requirements.','Register on the official PM Internship portal, create the candidate profile, select internships and submit applications to eligible opportunities.','https://pminternship.mca.gov.in/','assets/images/schemes/pm-internship.jpg','active'),
('PM-USP Central Sector Scheme of Scholarship for College and University Students (CSSS)','Education','All India','college scholarship, csss, pm-usp, students, higher education','Merit-cum-means scholarship support for students pursuing higher education.','The PM-USP Central Sector Scheme of Scholarship for College and University Students provides financial assistance to meritorious students from families with limited income while they pursue regular higher education.','Students who are above the prescribed Class 12 percentile threshold, pursue eligible regular degree courses and satisfy the family-income and other scholarship conditions.','Current eligibility includes being above the 80th percentile of the relevant Class 12 board, family income up to ₹4.5 lakh, regular recognised degree study and non-duplication with other scholarships.','₹12,000 per year at graduation level for the first three years, with higher rates for eligible later years/professional courses as specified by the scheme.','Class 12 marksheet; income certificate; caste certificate where applicable; disability certificate where applicable; Aadhaar-seeded bank account details.','Apply through the National Scholarship Portal (NSP) after completing the current OTR/registration process and submit the scholarship application and documents.','https://scholarships.gov.in/','assets/images/schemes/pm-usp-csss.jpg','active'),
('PM-YASASVI Pre-Matric Scholarship for OBC, EBC and DNT Students','Education','All India','pm yasasvi, pre matric, obc, ebc, dnt, scholarship','Scholarship assistance for eligible OBC, EBC and DNT students in Classes IX-X.','This PM-YASASVI sub-scheme provides educational assistance to eligible OBC, EBC and DNT students studying in government schools at the pre-matric stage.','Indian students in Classes IX and X in government schools who belong to the eligible OBC/EBC/DNT categories and satisfy family-income and other conditions.','Current scheme rules include annual family income up to ₹2.5 lakh, full-time study in government schools, valid category certification and regular attendance requirements.','Consolidated academic allowance of ₹4,000 per annum under the current scheme framework, paid through DBT.','Aadhaar; caste/community certificate; income certificate; domicile; educational records; bank account details; disability certificate if applicable.','Apply through the National Scholarship Portal or the state/UT scholarship route notified for the current academic year.','https://scholarships.gov.in/','assets/images/schemes/pm-yasasvi-pre.jpg','active'),
('PM-YASASVI Top Class College Education for OBC, EBC and DNT Students','Education','All India','pm yasasvi, top class, obc, ebc, dnt, college scholarship','Higher-education scholarship support for eligible OBC, EBC and DNT students in notified institutions.','The Top Class College Education component of PM-YASASVI provides full financial support to eligible OBC, EBC and DNT students pursuing higher education in notified institutions.','OBC/EBC/DNT students admitted to eligible full-time courses beyond Class XII in institutions included under the scheme, with family income within the prescribed ceiling.','Current rules include family income up to ₹2.5 lakh and admission in notified institutions; scholarship availability is subject to slots and annual notification.','Support can include tuition/non-refundable fees, living expenses, books/stationery and computer/laptop support as per the scheme rules.','Aadhaar; income certificate; category certificate; admission/bonafide proof; academic records; bank account details.','Apply through the National Scholarship Portal during the notified application window and complete institution/state verification.','https://scholarships.gov.in/','assets/images/schemes/pm-yasasvi-top-class.jpg','active'),
('AICTE-Swanath Scholarship Scheme for Students','Education','All India','aicte swanath, scholarship, orphan, covid, armed forces, student','Scholarship support for eligible students facing specified family circumstances.','The AICTE-Swanath Scholarship Scheme supports eligible diploma/degree students in AICTE-approved institutions who are orphans, lost parent(s) due to COVID-19, or are wards of Armed Forces/Central Paramilitary Forces personnel martyred in action.','Eligible students in regular AICTE-approved diploma/degree courses who meet the category and family-income conditions.','Family income should not exceed ₹8 lakh per annum under the current scheme; applicants must meet the specified orphan/COVID-19/shaheed category and scholarship non-duplication rules.','₹50,000 per annum for the permitted scholarship duration, subject to current AICTE guidelines.','Death/shaheed certificate or prescribed proof; bonafide certificate; marksheets; income certificate; category certificate where applicable; Aadhaar/bank details.','Apply through the National Scholarship Portal/AICTE scholarship process during the notified application window.','https://scholarships.gov.in/','assets/images/schemes/aicte-swanath.jpg','active'),
('National Means-cum-Merit Scholarship Scheme (NMMSS)','Education','All India','nmmss, scholarship, class 8, merit, school','Merit-cum-means scholarship for eligible students entering Classes IX-XII.','NMMSS is intended to reduce dropout after Class VIII and encourage continuation of secondary education among meritorious students from economically weaker families.','Meritorious students studying in eligible schools who qualify through the prescribed state/UT selection test and meet the family-income condition.','The scheme has a parental income ceiling and selection is based on the prescribed state/UT-level process; current examination and school criteria apply.','₹12,000 per year for eligible scholarship holders, subject to renewal conditions and current guidelines.','Income certificate; school records; marks/selection-test records; Aadhaar/identity and bank account details as required.','Apply through the state/UT selection process and the National Scholarship Portal after selection/eligibility as notified.','https://scholarships.gov.in/','assets/images/schemes/nmmss.jpg','active'),
('Post-Matric Scholarship for Scheduled Caste (SC) Students','Education','All India','post matric, scholarship, sc, scheduled caste, students','Financial assistance for eligible SC students pursuing post-matriculation studies.','The Post-Matric Scholarship for SC Students supports eligible Scheduled Caste students pursuing recognised post-matric courses, with scholarship components and income rules specified in the applicable guidelines.','SC students enrolled in eligible post-matriculation courses who meet the current family-income, institution and academic conditions.','Eligibility depends on recognised course/institution, SC status, family income ceiling and other current scholarship rules; state/UT implementation also applies.','Scholarship assistance covering eligible compulsory fees and academic/maintenance components according to the prevailing scheme guidelines.','SC certificate; income certificate; educational records; bonafide/admission proof; Aadhaar; bank account details.','Apply through the National Scholarship Portal or the designated state/UT scholarship portal during the notified application period.','https://scholarships.gov.in/','assets/images/schemes/post-matric-sc.jpg','active'),
('AICTE Pragati Scholarship Scheme for Girl Students','Education','All India','aicte pragati, girls scholarship, technical education, diploma, degree','Scholarship support for eligible girl students pursuing AICTE-approved technical education.','AICTE Pragati provides scholarship support intended to promote technical education among eligible girl students enrolled in AICTE-approved diploma or degree programmes.','Girl students admitted to eligible AICTE-approved diploma/degree courses who satisfy the applicable family-income and academic conditions.','Eligibility, family-income ceiling, number of scholarships and renewal requirements follow the current AICTE/NSP notification.','Scholarship assistance towards education-related expenses as notified by AICTE for the relevant academic year.','Income certificate; admission/bonafide certificate; academic records; Aadhaar; bank account; caste/disability documents where applicable.','Apply through the National Scholarship Portal under the AICTE scholarship section during the notified application window.','https://scholarships.gov.in/','assets/images/schemes/aicte-pragati.jpg','active'),
('AICTE Saksham Scholarship Scheme for Specially Abled Students','Education & Disability','All India','aicte saksham, disability scholarship, technical education, student','Scholarship support for eligible specially abled students in technical education.','AICTE Saksham supports eligible specially abled students pursuing AICTE-approved technical diploma or degree programmes.','Eligible students with specified disability status enrolled in approved technical education courses and meeting the current income and other conditions.','Disability certification, income ceiling, approved institution/course and other criteria are governed by the current AICTE notification.','Scholarship assistance for academic and related expenses as notified by AICTE for the relevant year.','Disability certificate; income certificate; admission/bonafide certificate; academic records; Aadhaar; bank account details.','Apply through the National Scholarship Portal during the notified AICTE scholarship application cycle.','https://scholarships.gov.in/','assets/images/schemes/aicte-saksham.jpg','active'),
('Mukhyamantri Yuva Swavalamban Yojana (MYSY)','Education','Gujarat','mysy, gujarat scholarship, diploma, engineering, medical, students','Gujarat scholarship support for economically weaker students pursuing higher education.','MYSY is a Gujarat Government scholarship scheme supporting eligible students from economically weaker sections who pursue diploma, degree and professional higher-education courses.','Eligible Gujarat students pursuing notified diploma, degree and professional courses who satisfy the merit and income conditions.','Current rules include course-specific academic requirements and parental annual income not exceeding ₹6 lakh, with additional conditions for different programmes.','Tuition-fee grant, hostel support and book/instrument assistance, with limits depending on course and current state guidelines.','Academic marksheets; Gujarat residence/domicile documents; income certificate; admission/bonafide proof; Aadhaar; bank account details; other course documents.','Apply through the official MYSY portal and complete the online application and document-verification process.','https://mysy.guj.nic.in/','assets/images/schemes/mysy.jpg','active'),
('Scholarship Scheme for Students Studying in Government Colleges - Gujarat','Education','Gujarat','gujarat, government college, scholarship, arts, commerce, science','Scholarship for meritorious students studying in government colleges in Gujarat.','This Gujarat Education Department scheme provides annual scholarship support to meritorious students studying Arts, Commerce or Science in government colleges.','Gujarat-resident students studying in eligible government colleges and meeting the merit criteria under the scheme.','The current myScheme guidance specifies Gujarat residency, study in a government college, HSC qualification and top-rank performance at university level in the relevant stream.','Annual scholarship of ₹3,000 for Science, ₹2,000 for Commerce and ₹1,000 for Arts under the current scheme information.','HSC pass certificate/marksheet; graduate or course marksheet; Aadhaar/bank details; other documents as required.','Apply through the Digital Gujarat portal using the relevant scholarship service and complete profile/application verification.','https://www.digitalgujarat.gov.in/','assets/images/schemes/gujarat-govt-college-scholarship.jpg','active'),
('Pre-Matric Scholarship for Students of Socially and Educationally Backward Class - Gujarat','Education','Gujarat','gujarat, sebc, pre matric, scholarship, school','Educational assistance for eligible SEBC students in Classes I-X.','This Gujarat Social Justice and Empowerment Department scheme provides scholarship assistance to socially and educationally backward class students in eligible government and aided schools.','SEBC students studying in Standards 1 to 10 in eligible government/aided schools in Gujarat.','For Standards 1-8 there is no family-income ceiling under the current information; for Standards 9-10 the family income should not exceed ₹6 lakh per annum.','Current scholarship amounts range from ₹500 to ₹1,000 per year depending on gender and class under the notified scheme structure.','Caste certificate; income certificate where applicable; school bonafide certificate; previous marksheet; bank passbook; Aadhaar; passport photo.','Apply through the Digital Gujarat portal and select the relevant scholarship service, then complete document upload and submission.','https://www.digitalgujarat.gov.in/','assets/images/schemes/gujarat-sebc-pre-matric.jpg','active'),
('PMMSY - Small Biofloc Establishment (Gujarat)','Fisheries','Gujarat','gujarat, biofloc, fish farming, pmmsy, subsidy','Financial assistance for eligible small biofloc fish-farming units in Gujarat.','This Gujarat PMMSY component promotes inland fish farming using biofloc technology and provides eligible beneficiaries with financial assistance for establishing a small biofloc unit.','Individuals, societies, SHGs, associations, reservoir lease holders and private entities involved in inland fisheries, subject to current component conditions.','Applicant must generally be above 18, have a bank account, and own suitable land or hold a qualifying long-term lease where construction assistance is involved.','For the notified small biofloc unit, the current myScheme information states a unit cost of ₹7.5 lakh, with 40% assistance for general category and higher assistance provisions for eligible women/SC/ST categories subject to rules.','Identity proof; bank details; land ownership/lease proof; co-owner consent if applicable; SC/ST certificate where applicable.','Apply through the Gujarat i-Khedut agriculture/fisheries scheme route as notified and complete the online application, correction and confirmation steps.','https://www.myscheme.gov.in/schemes/pmmsysbeguj','assets/images/schemes/gujarat-biofloc.jpg','active'),
('COP-34 Financial Assistance to Farmer for Interest Subvention (Kisan Credit Card Interest Assistance) - Gujarat','Agriculture','Gujarat','gujarat farmer, kcc interest assistance, crop loan, interest subsidy','Gujarat assistance for timely repayment of eligible KCC-linked crop loans.','This Gujarat Agriculture, Farmers Welfare and Cooperation Department scheme provides interest subvention support on eligible short-term crop loans when the farmer repays the loan on time.','Farmers who have taken eligible short-term Kharif crop loans through specified lending institutions and meet the repayment conditions.','The current myScheme information requires an eligible farmer, a qualifying Kharif crop loan and timely repayment; the scheme is limited to specified loan types and periods.','4% interest subvention on timely repayment of eligible crop loans up to ₹3 lakh, subject to the current scheme rules.','KCC/crop-loan documents; proof of timely repayment; Aadhaar/identity proof; land/cultivation documents; other bank/government records as required.','The farmer generally does not apply directly; the lending bank submits the integrated proposal through the prescribed Gujarat government process.','https://www.myscheme.gov.in/schemes/fafiskc','assets/images/schemes/gujarat-kcc-interest.jpg','active');
